using System;using System.Linq;using System.Drawing;using System.IO;using System.Collections.Generic;using System.Windows.Forms;using MakroSoundSwitch;
class OfflineBackend:IFeatureBackend{public List<Device> Outputs=new List<Device>(),Inputs=new List<Device>();public List<string> Actions=new List<string>();public List<Device> ListDevices(int flow){return flow==0?Outputs:Inputs;}public string GetDefault(int flow,int role){return "original";}public void SetDefault(string id,int role){Actions.Add(id+":"+role);}public void SendMedia(FeatureType type){Actions.Add(type.ToString());}public void Mute(){Actions.Add("Mute");}}
class OfflineToastVerify {
 static void Check(bool b,string text){if(!b)throw new Exception(text);Console.WriteLine("PASS: "+text);}
 [STAThread]static void Main(){Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);var output=new ScenarioFeature{Type=FeatureType.Output,DeviceId="headset",DeviceName="Headset"};var input=new ScenarioFeature{Type=FeatureType.Input,DeviceId="microphone",DeviceName="Microphone"};var backend=new OfflineBackend();var scenario=new Scenario{Name="Desk setup",Features=new List<ScenarioFeature>{output,input}};var result=FeatureRunner.Run(scenario,backend);Check(result.Completed==0&&result.Skipped.Count==2&&backend.Actions.Count==0,"Scenario activates when both selected devices are absent");Check(output.DeviceId=="headset"&&input.DeviceId=="microphone","Offline activation never erases saved device selections");
 backend.Inputs.Add(new Device{Id="microphone",Name="Microphone"});scenario.Features.Add(new ScenarioFeature{Type=FeatureType.PlayPauseMedia});result=FeatureRunner.Run(scenario,backend);Check(result.Completed==2&&result.Skipped.Count==1&&backend.Actions.SequenceEqual(new[]{"microphone:0","microphone:1","microphone:2","PlayPauseMedia"}),"Connected input and playback run in order when output is unplugged");backend.Outputs.Add(new Device{Id="headset",Name="Headset"});backend.Actions.Clear();result=FeatureRunner.Run(scenario,backend);Check(result.Completed==3&&result.Skipped.Count==0&&backend.Actions[0]=="headset:0","Saved output works again after reconnecting");
 backend=new OfflineBackend();result=FeatureRunner.Run(new Scenario{Features=new List<ScenarioFeature>{new ScenarioFeature{Type=FeatureType.MuteMedia},new ScenarioFeature{Type=FeatureType.PlayPauseMedia}}},backend);Check(result.Completed==1&&result.Skipped.Count==1&&backend.Actions.Single()=="PlayPauseMedia","No-output mute is skipped without blocking media playback");
 using(var host=new Form())using(var toast=new ScenarioToast()){host.Show();host.Activate();Application.DoEvents();var focused=Form.ActiveForm;toast.ShowScenario("Desk setup",new ScenarioRunResult{Completed=2,Skipped=new List<string>{"Headset disconnected"}});Application.DoEvents();Check(toast.Visible&&!toast.ShowInTaskbar,"Small toast is visible without a taskbar entry");Check(Form.ActiveForm==focused,"Toast does not take keyboard focus");using(var image=new Bitmap(toast.Width,toast.Height)){toast.DrawToBitmap(image,new Rectangle(Point.Empty,toast.Size));image.Save("offline-toast-preview.png");}toast.ShowScenario("Music",new ScenarioRunResult{Completed=1});Check(toast.Visible,"Repeated scenario changes reuse the toast");var start=DateTime.UtcNow;while((DateTime.UtcNow-start).TotalMilliseconds<2800){Application.DoEvents();System.Threading.Thread.Sleep(10);}Check(!toast.Visible,"Toast disappears automatically");host.Close();}
 }
}
